def predict(parameters, stimulus, history):
    import numpy as np

    # The subject has a strict preference for either Option A (0) or Option B (1)
    pref = int(parameters["preferred_option"])

    if pref == 0:
        return np.array([1.0, 0.0])
    else:
        return np.array([0.0, 1.0])

